cat > "$OUT/detail2.py" <<'PY'
import os,json
from volatility3.plugins.windows import windows
class Detail2(windows.Windows):
 def _generator(self):
  out=[]
  for sn,dn,w,wn in self.list_windows(self.context,self.config_path,self.config['kernel']):
   if w.vol.offset != 0xbd5b448f45b0: continue
   row={'window':hex(w.vol.offset),'name':wn,'type':w.vol.type_name,'size':w.vol.size,'layer':w.vol.layer_name}
   lay=self.context.layers[w.vol.layer_name]
   row['hex']=lay.read(w.vol.offset,1024,pad=True).hex()
   for attr in ['subPointer','strName','cbwndExtra','dwUserData','spwndParent','spwndOwner','pcls','style','ExStyle','lpfnWndProc']:
    try:
     v=getattr(w,attr); row[attr]=str(v)
     try:
      d=v.dereference(); row[attr+'_deref']={'address':hex(d.vol.offset),'type':d.vol.type_name,'layer':d.vol.layer_name,'hex':self.context.layers[d.vol.layer_name].read(d.vol.offset,4096,pad=True).hex()}
     except Exception as e: row[attr+'_deref_error']=str(e)
    except Exception as e: row[attr+'_error']=str(e)
   out.append(row)
  json.dump(out,open(os.environ['DETAIL_OUT'],'w'),indent=2)
  yield from super()._generator()
PY
